YEAR_UNITS.forEach(u=>{
 u.coreVocab=[...u.vocab];
 const anchors=u.coreVocab.filter(w=>! /\s/.test(w.en.trim())&&!assignedWords.has(w.en.toLowerCase())).filter((w,i,a)=>a.findIndex(x=>x.en.toLowerCase()===w.en.toLowerCase())===i);
 anchors.forEach(w=>assignedWords.add(w.en.toLowerCase()));
 const needed=weeklyQuota(u.week)-anchors.length;
 const extra=[];
 for(let i=0;i<additions.length&&extra.length<needed;){const w=additions[i];if(u.week<40&&laterNewsWords.has(w.en)){i++;continue;}extra.push(w);additions.splice(i,1);assignedWords.add(w.en.toLowerCase());}
 if(extra.length!==needed)throw Error('Incomplete word plan for week '+u.week);
 const phrases=u.coreVocab.filter(w=>/\s/.test(w.en.trim())&&!assignedPhrases.has(w.en.toLowerCase()));phrases.forEach(w=>assignedPhrases.add(w.en.toLowerCase()));
 u.words=[...anchors,...extra];u.phrases=phrases;u.vocab=[...u.words,...phrases];
 const count=u.words.length/6;
 u.dailyWords=Array.from({length:6},(_,i)=>[...u.words.slice(i*count,(i+1)*count),...phrases.filter((_,j)=>j%6===i)]);
 u.dailyWords.forEach((list,i)=>list.forEach(w=>{const day=(u.week-1)*7+i+1;WORD_INTRO_DAY.set(w.id,day);w.introDay=day;}));
});
